python - <<'PY'
from functools import partial
from http.server import SimpleHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import json
import subprocess
import threading
import time

artifact = Path("/tmp/2026-08-21_05-18-15_explanation-scope-governor-skill.html")
handler = partial(SimpleHTTPRequestHandler, directory="/tmp")
server = ThreadingHTTPServer(("127.0.0.1", 0), handler)
thread = threading.Thread(target=server.serve_forever, daemon=True)
thread.start()
url = f"http://127.0.0.1:{server.server_port}/{artifact.name}"
session = "scope-gov-explainer"
results = {}

def cli(*args, raw=False):
    cmd = ["playwright-cli", f"-s={session}"]
    if raw:
        cmd.append("--raw")
    cmd.extend(args)
    proc = subprocess.run(cmd, capture_output=True, text=True)
    return proc.returncode, proc.stdout, proc.stderr

code, out, err = cli("open", url)
results["open_rc"] = code
results["open_err"] = err[-500:] if err else ""
time.sleep(0.4)

code, out, err = cli("console")
results["console"] = out.strip()
results["console_err"] = err.strip()

def evaluate(expr):
    wrapped = f"async page => await page.evaluate(() => JSON.stringify({expr}))"
    code, out, err = cli("--raw", "run-code", wrapped) if False else (None, None, None)
    proc = subprocess.run(
        ["playwright-cli", f"-s={session}", "--raw", "run-code", wrapped],
        capture_output=True, text=True,
    )
    if proc.returncode != 0:
        return {"error": proc.stderr or proc.stdout}
    text = proc.stdout.strip()
    try:
        value = json.loads(text)
        return json.loads(value) if isinstance(value, str) else value
    except Exception:
        return {"raw": text, "stderr": proc.stderr}

state = evaluate(
    "({"
    "title: document.title,"
    "prompt: document.querySelector('.quiz-question h3')?.textContent || '',"
    "answers: [...document.querySelectorAll('.answer-list button')].map(b => b.textContent),"
    "feedbackVisible: document.querySelector('.feedback')?.dataset.visible,"
    "score: document.querySelector('#quiz-score')?.textContent"
    "})"
)
results["initial"] = state

# Click correct answer by matching page JSON
click_correct = evaluate(
    """(() => {
      const q = JSON.parse(document.querySelector('#explainer-quiz-data').textContent);
      const heading = document.querySelector('.quiz-question h3')?.textContent || '';
      const prompt = heading.replace(/^\\d+\\.\\s*/, '');
      const question = q.questions.find(item => item.prompt === prompt);
      const correct = question.answers.find(a => a.correct).text;
      const button = [...document.querySelectorAll('.answer-list button')].find(b => b.textContent === correct);
      button.click();
      const feedback = document.querySelector('.feedback');
      return {
        clicked: correct,
        visible: feedback.dataset.visible,
        correctAttr: feedback.dataset.correct,
        text: feedback.textContent,
        score: document.querySelector('#quiz-score')?.textContent
      };
    })()"""
)
results["correct_click"] = click_correct

# Reset then click incorrect
reset = evaluate(
    """(() => {
      document.querySelector('#quiz-reset').click();
      const heading = document.querySelector('.quiz-question h3')?.textContent || '';
      const feedback = document.querySelector('.feedback');
      return {
        prompt: heading,
        feedbackVisible: feedback?.dataset.visible,
        score: document.querySelector('#quiz-score')?.textContent,
        selected: [...document.querySelectorAll('.answer-list button')].some(b => b.dataset.selected === 'true')
      };
    })()"""
)
results["after_reset"] = reset

wrong_click = evaluate(
    """(() => {
      const q = JSON.parse(document.querySelector('#explainer-quiz-data').textContent);
      const heading = document.querySelector('.quiz-question h3')?.textContent || '';
      const prompt = heading.replace(/^\\d+\\.\\s*/, '');
      const question = q.questions.find(item => item.prompt === prompt);
      const wrong = question.answers.find(a => !a.correct).text;
      const button = [...document.querySelectorAll('.answer-list button')].find(b => b.textContent === wrong);
      button.click();
      const feedback = document.querySelector('.feedback');
      return {
        clicked: wrong,
        visible: feedback.dataset.visible,
        correctAttr: feedback.dataset.correct,
        text: feedback.textContent
      };
    })()"""
)
results["wrong_click"] = wrong_click

before_rand = evaluate("document.querySelector('.quiz-question h3')?.textContent")
rand = evaluate(
    """(() => {
      const beforePrompt = document.querySelector('.quiz-question h3')?.textContent;
      const beforeAnswers = [...document.querySelectorAll('.answer-list button')].map(b => b.textContent);
      document.querySelector('#quiz-randomize').click();
      const afterPrompt = document.querySelector('.quiz-question h3')?.textContent;
      const afterAnswers = [...document.querySelectorAll('.answer-list button')].map(b => b.textContent);
      const feedback = document.querySelector('.feedback');
      return {
        beforePrompt, afterPrompt,
        beforeAnswers, afterAnswers,
        changed: beforePrompt !== afterPrompt || JSON.stringify(beforeAnswers) !== JSON.stringify(afterAnswers),
        feedbackVisible: feedback?.dataset.visible,
        score: document.querySelector('#quiz-score')?.textContent
      };
    })()"""
)
results["randomize"] = rand

overflow = evaluate(
    """(() => {
      // resize happens outside
      return { inner: window.innerWidth };
    })()"""
)

proc = subprocess.run(
    ["playwright-cli", f"-s={session}", "resize", "390", "844"],
    capture_output=True, text=True,
)
results["resize_rc"] = proc.returncode
time.sleep(0.2)
overflow = evaluate(
    """(() => {
      const doc = document.documentElement;
      const body = document.body;
      return {
        innerWidth: window.innerWidth,
        scrollWidth: Math.max(doc.scrollWidth, body.scrollWidth),
        clientWidth: doc.clientWidth,
        overflow: Math.max(doc.scrollWidth, body.scrollWidth) > doc.clientWidth + 1
      };
    })()"""
)
results["overflow"] = overflow

subprocess.run(["playwright-cli", f"-s={session}", "close"], capture_output=True, text=True)
server.shutdown()
print(json.dumps(results, indent=2, ensure_ascii=False)[:12000])
PY
